window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5d7e1cebdb7810b4"]={"versions": [{"id": "FIG-5d7e1cebdb7810b4", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Systemarchitektur). Das Diagramm visualisiert die serviceorientierte Schnittstellenbeziehung zwischen den beiden Functional Clustern State Management und Network Management.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert zwei AUTOSAR Adaptive Functional Cluster sowie ein Service-Interface:</p>\n<ul class=\"fig-list\">\n<li>Functional Cluster <code>State Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Nutzt über eine Abhängigkeit (<code>«use»</code>, <code>«aapRequiredPort»</code>) die Schnittstelle als Konsument (Client/Subscriber).</li>\n<li>Functional Cluster <code>Network Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>): Realisiert bzw. stellt die Schnittstelle über einen Provided Port (<code>«aapProvidedPort»</code>, Realisierungspfeil mit geschlossener Dreiecksspitze) bereit.</li>\n<li>Service-Interface <code>NetworkState_{NetworkHandle}</code> (Stereotypen <code>«aapAraComServiceInterface,aapAPI»</code>): Parametrisiert über das Netzwerk-Handle. Es deklariert zwei zugriffsgeschützte Service-Felder (<code>«aapAccessControlled, aapServiceField»</code>):</li>\n<li><code>+ NetworkCurrentState</code></li>\n<li><code>+ NetworkRequestedState</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Interaktionsmuster über ara::com (Service-Oriented Communication):</p>\n<ul class=\"fig-list\">\n<li>Das State Management bindet das Network Management über einen Required Port an das Service-Interface <code>NetworkState_{NetworkHandle}</code> an.</li>\n<li>Über die Felder <code>NetworkCurrentState</code> und <code>NetworkRequestedState</code> interagiert das State Management mit dem Network Management über Standard-Feldmechanismen (Get/Set/Notifier) zur Abfrage und Steuerung des aktuellen sowie des angeforderten Netzwerkzustands.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für Adaptive Platform Architekten und Entwickler:</p>\n<ul class=\"fig-list\">\n<li>Die Kommunikation zwischen State Management und Network Management erfolgt über ein typisiertes ara::com-Service-Interface.</li>\n<li>Der Zugriff auf <code>NetworkCurrentState</code> und <code>NetworkRequestedState</code> unterliegt der Zugriffskontrolle (<code>«aapAccessControlled»</code>).</li>\n<li>Implementierungen müssen sicherstellen, dass pro Netzwerk-Instanz (<code>{NetworkHandle}</code>) ein entsprechendes Service-Interface bereitgestellt und über die ara::com-Middleware instanziiert wird.</li>\n</ul>"}, {"id": "FIG-c2f35409d85845f7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Systemarchitektur). Das Diagramm visualisiert die serviceorientierte Schnittstellenbeziehung zwischen den beiden Functional Clustern State Management und Network Management.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert zwei AUTOSAR Adaptive Functional Cluster sowie ein Service-Interface:</p>\n<ul class=\"fig-list\">\n<li>Functional Cluster <code>State Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Nutzt über eine Abhängigkeit (<code>«use»</code>, <code>«aapRequiredPort»</code>) die Schnittstelle als Konsument (Client/Subscriber).</li>\n<li>Functional Cluster <code>Network Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>): Realisiert bzw. stellt die Schnittstelle über einen Provided Port (<code>«aapProvidedPort»</code>, Realisierungspfeil mit geschlossener Dreiecksspitze) bereit.</li>\n<li>Service-Interface <code>NetworkState_{NetworkHandle}</code> (Stereotypen <code>«aapAraComServiceInterface,aapAPI»</code>): Parametrisiert über das Netzwerk-Handle. Es deklariert zwei zugriffsgeschützte Service-Felder (<code>«aapAccessControlled, aapServiceField»</code>):</li>\n<li><code>+ NetworkCurrentState</code></li>\n<li><code>+ NetworkRequestedState</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Interaktionsmuster über ara::com (Service-Oriented Communication):</p>\n<ul class=\"fig-list\">\n<li>Das State Management bindet das Network Management über einen Required Port an das Service-Interface <code>NetworkState_{NetworkHandle}</code> an.</li>\n<li>Über die Felder <code>NetworkCurrentState</code> und <code>NetworkRequestedState</code> interagiert das State Management mit dem Network Management über Standard-Feldmechanismen (Get/Set/Notifier) zur Abfrage und Steuerung des aktuellen sowie des angeforderten Netzwerkzustands.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für Adaptive Platform Architekten und Entwickler:</p>\n<ul class=\"fig-list\">\n<li>Die Kommunikation zwischen State Management und Network Management erfolgt über ein typisiertes ara::com-Service-Interface.</li>\n<li>Der Zugriff auf <code>NetworkCurrentState</code> und <code>NetworkRequestedState</code> unterliegt der Zugriffskontrolle (<code>«aapAccessControlled»</code>).</li>\n<li>Implementierungen müssen sicherstellen, dass pro Netzwerk-Instanz (<code>{NetworkHandle}</code>) ein entsprechendes Service-Interface bereitgestellt und über die ara::com-Middleware instanziiert wird.</li>\n</ul>"}, {"id": "FIG-13eb484cd922e330", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Systemarchitektur). Das Diagramm visualisiert die Schnittstellenbeziehung zwischen den Functional Clustern State Management und Network Management über ein direktes C++-Port-Interface (API).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei AUTOSAR Adaptive Functional Cluster sowie ein Port-Interface:</p>\n<ul class=\"fig-list\">\n<li>Functional Cluster <code>State Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Fungiert als Nutzer (<code>«use»</code>, <code>«aapRequiredPort»</code>) der Schnittstelle.</li>\n<li>Functional Cluster <code>Network Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>): Realisiert das Interface (Realisierungspfeil mit geschlossener Dreiecksspitze).</li>\n<li>Port-Interface <code>NetworkHandle</code> (Stereotypen <code>«aapAPI,aapPortInterface»</code>): Methodenbasierte Schnittstelle mit folgenden Operationen:</li>\n<li><code>+ GetNetworkRequestedState()</code></li>\n<li><code>+ GetNetworkState()</code></li>\n<li><code>+ RegisterNetworkRequestedStateChangeNotifier()</code></li>\n<li><code>+ RegisterNetworkStateChangeNotifier()</code></li>\n<li><code>+ SetNetworkRequestedState()</code></li>\n<li><code>+ UnregisterNetworkRequestedStateChangeNotifier()</code></li>\n<li><code>+ UnregisterNetworkStateChangeNotifier()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Interaktionsmuster über direkte API-Aufrufe (C++ Port-Interface):</p>\n<ul class=\"fig-list\">\n<li>Das State Management fordert über <code>SetNetworkRequestedState()</code> Netzwerkzustandsänderungen an.</li>\n<li>Der aktuelle und der angeforderte Zustand können synchron über <code>GetNetworkState()</code> und <code>GetNetworkRequestedState()</code> abgefragt werden.</li>\n<li>Zustandsänderungsbenachrichtigungen werden über Observer-Registrierung (<code>RegisterNetworkStateChangeNotifier()</code>, <code>RegisterNetworkRequestedStateChangeNotifier()</code>) und Deregistrierung (<code>Unregister...</code>) synchronisiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für Adaptive Platform Architekten und Entwickler:</p>\n<ul class=\"fig-list\">\n<li>Die Kopplung zwischen State Management und Network Management erfolgt über eine standardisierte funktionale C++-API (<code>«aapAPI,aapPortInterface»</code>).</li>\n<li>Das Interface <code>NetworkHandle</code> erzwingt eine explizite Registrierung von Callbacks/Notifiers für Statusaktualisierungen und stellt synchrone Getter-/Setter-Methoden bereit.</li>\n</ul>"}, {"id": "FIG-48268bb28bf27487", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Systemarchitektur). Das Diagramm visualisiert die Schnittstellenbeziehung zwischen den Functional Clustern State Management und Network Management über ein direktes C++-Port-Interface (API).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei AUTOSAR Adaptive Functional Cluster sowie ein Port-Interface:</p>\n<ul class=\"fig-list\">\n<li>Functional Cluster <code>State Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Fungiert als Nutzer (<code>«use»</code>, <code>«aapRequiredPort»</code>) der Schnittstelle.</li>\n<li>Functional Cluster <code>Network Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>): Realisiert das Interface (Realisierungspfeil mit geschlossener Dreiecksspitze).</li>\n<li>Port-Interface <code>NetworkHandle</code> (Stereotypen <code>«aapAPI,aapPortInterface»</code>): Methodenbasierte Schnittstelle mit folgenden Operationen:</li>\n<li><code>+ GetNetworkRequestedState()</code></li>\n<li><code>+ GetNetworkState()</code></li>\n<li><code>+ RegisterNetworkRequestedStateChangeNotifier()</code></li>\n<li><code>+ RegisterNetworkStateChangeNotifier()</code></li>\n<li><code>+ SetNetworkRequestedState()</code></li>\n<li><code>+ UnregisterNetworkRequestedStateChangeNotifier()</code></li>\n<li><code>+ UnregisterNetworkStateChangeNotifier()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Interaktionsmuster über direkte API-Aufrufe (C++ Port-Interface):</p>\n<ul class=\"fig-list\">\n<li>Das State Management fordert über <code>SetNetworkRequestedState()</code> Netzwerkzustandsänderungen an.</li>\n<li>Der aktuelle und der angeforderte Zustand können synchron über <code>GetNetworkState()</code> und <code>GetNetworkRequestedState()</code> abgefragt werden.</li>\n<li>Zustandsänderungsbenachrichtigungen werden über Observer-Registrierung (<code>RegisterNetworkStateChangeNotifier()</code>, <code>RegisterNetworkRequestedStateChangeNotifier()</code>) und Deregistrierung (<code>Unregister...</code>) synchronisiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für Adaptive Platform Architekten und Entwickler:</p>\n<ul class=\"fig-list\">\n<li>Die Kopplung zwischen State Management und Network Management erfolgt über eine standardisierte funktionale C++-API (<code>«aapAPI,aapPortInterface»</code>).</li>\n<li>Das Interface <code>NetworkHandle</code> erzwingt eine explizite Registrierung von Callbacks/Notifiers für Statusaktualisierungen und stellt synchrone Getter-/Setter-Methoden bereit.</li>\n</ul>"}, {"id": "FIG-d7ef80c65c369f12", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Systemarchitektur). Das Diagramm visualisiert die Schnittstellenbeziehung zwischen den Functional Clustern State Management und Network Management über ein direktes C++-Port-Interface (API).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei AUTOSAR Adaptive Functional Cluster sowie ein Port-Interface:</p>\n<ul class=\"fig-list\">\n<li>Functional Cluster <code>State Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Fungiert als Nutzer (<code>«use»</code>, <code>«aapRequiredPort»</code>) der Schnittstelle.</li>\n<li>Functional Cluster <code>Network Management</code> (Stereotyp <code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Realisiert das Interface (Realisierungspfeil mit geschlossener Dreiecksspitze).</li>\n<li>Port-Interface <code>NetworkHandle</code> (Stereotypen <code>«aapAPI,aapPortInterface»</code>): Methodenbasierte Schnittstelle mit folgenden Operationen:</li>\n<li><code>+ GetNetworkRequestedState()</code></li>\n<li><code>+ GetNetworkState()</code></li>\n<li><code>+ RegisterNetworkRequestedStateChangeNotifier()</code></li>\n<li><code>+ RegisterNetworkStateChangeNotifier()</code></li>\n<li><code>+ SetNetworkRequestedState()</code></li>\n<li><code>+ UnregisterNetworkRequestedStateChangeNotifier()</code></li>\n<li><code>+ UnregisterNetworkStateChangeNotifier()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Interaktionsmuster über direkte API-Aufrufe (C++ Port-Interface):</p>\n<ul class=\"fig-list\">\n<li>Das State Management fordert über <code>SetNetworkRequestedState()</code> Netzwerkzustandsänderungen an.</li>\n<li>Der aktuelle und der angeforderte Zustand können synchron über <code>GetNetworkState()</code> und <code>GetNetworkRequestedState()</code> abgefragt werden.</li>\n<li>Zustandsänderungsbenachrichtigungen werden über Observer-Registrierung (<code>RegisterNetworkStateChangeNotifier()</code>, <code>RegisterNetworkRequestedStateChangeNotifier()</code>) und Deregistrierung (<code>Unregister...</code>) synchronisiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für Adaptive Platform Architekten und Entwickler:</p>\n<ul class=\"fig-list\">\n<li>Sowohl State Management als auch Network Management sind als <code>daemon-based</code> Functional Cluster klassifiziert.</li>\n<li>Die Kopplung zwischen beiden Clustern erfolgt über die funktionale C++-API <code>NetworkHandle</code> (<code>«aapAPI,aapPortInterface»</code>) mit Notifier-Registrierung und Getter/Setter-Methoden.</li>\n</ul>"}], "trans": [{"from": "FIG-5d7e1cebdb7810b4", "to": "FIG-c2f35409d85845f7", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2f35409d85845f7", "to": "FIG-13eb484cd922e330", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Die Schnittstelle wechselt von einem Service-Interface <code>«aapAraComServiceInterface,aapAPI» NetworkState_{NetworkHandle}</code> zu einem portbasierten C++-API-Interface <code>«aapAPI,aapPortInterface» NetworkHandle</code>.</li>\n<li>Die Service-Felder <code>«aapAccessControlled, aapServiceField» + NetworkCurrentState</code> und <code>+ NetworkRequestedState</code> entfallen.</li>\n<li>Als Interface-Operationen neu eingeführt werden: <code>+ GetNetworkRequestedState()</code>, <code>+ GetNetworkState()</code>, <code>+ RegisterNetworkRequestedStateChangeNotifier()</code>, <code>+ RegisterNetworkStateChangeNotifier()</code>, <code>+ SetNetworkRequestedState()</code>, <code>+ UnregisterNetworkRequestedStateChangeNotifier()</code> und <code>+ UnregisterNetworkStateChangeNotifier()</code>.</li>\n<li>Die Port-Realisierung durch das Functional Cluster <em>Network Management</em> verliert das Stereotyp <code>«aapProvidedPort»</code> (wird als reine Interface-Realisierung dargestellt).</li>\n</ul>"}, {"from": "FIG-13eb484cd922e330", "to": "FIG-48268bb28bf27487", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-48268bb28bf27487", "to": "FIG-d7ef80c65c369f12", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beim Functional Cluster <em>Network Management</em> wird die Eigenschaftsbezeichnung links unten um <code>daemon-based</code> ergänzt.</li>\n</ul>"}]};
